import { ERR_IMG } from "./consts";
import { preloadImage } from "../shared/BlurImage";
import dimensions from "../assets/images_md/dimensions.json";

// Resized WebP variants generated by optimize.py / blur.py (see repo root).
const MD_DIR = "/src/assets/images_md/";
const LG_DIR = "/src/assets/images_lg/";
const BLURRED_DIR = "/src/assets/images_blurred/";

const medium = import.meta.glob<string>(
  "/src/assets/images_md/**/*.{png,jpg,jpeg,webp,avif,gif}",
  {
    eager: true,
    import: "default",
  },
);
const large = import.meta.glob<string>(
  "/src/assets/images_lg/**/*.{png,jpg,jpeg,webp,avif,gif}",
  {
    eager: true,
    import: "default",
  },
);
const blurred = import.meta.glob<string>(
  "/src/assets/images_blurred/**/*.{png,jpg,jpeg,webp,avif,gif}",
  {
    eager: true,
    import: "default",
    query: "?inline",
  },
);

const normalize = (s: string) => s.toLowerCase().replace(/[-_]/g, " ");
const stripExt = (s: string) => s.replace(/\.[^./]+$/, "");

// variants are matched by their extensionless relative path
const byRel = (files: Record<string, string>, dir: string) =>
  new Map(
    Object.entries(files).map(([p, u]) => [stripExt(p.slice(dir.length)), u]),
  );
const largeByRel = byRel(large, LG_DIR);
const blurredByRel = byRel(blurred, BLURRED_DIR);

const dims = dimensions as Record<string, number[] | undefined>;
const imagesById: Record<string, ProjectImage[]> = {};

for (const [path, src] of Object.entries(medium).sort()) {
  const rel = stripExt(path.slice(MD_DIR.length));
  const slash = rel.lastIndexOf("/");
  if (slash === -1) continue;

  const id = rel.slice(0, slash);
  const name = rel.slice(slash + 1).replace(/[-_]/g, " ");

  (imagesById[id] ??= []).push({
    src,
    name,
    alt: name,
    blur: blurredByRel.get(rel),
    full: largeByRel.get(rel),
    width: dims[rel]?.[0],
    height: dims[rel]?.[1],
  });
}

const RESERVED = new Set(["cover", "header", "cover_main"].map(normalize));

export const getImages = (id: string, getAll = false): ProjectImage[] =>
  (imagesById[id] ?? []).filter(
    (img) => getAll || !RESERVED.has(normalize(img.name)),
  );

const findImage = (id: string, name: string) =>
  getImages(id, true).find((img) => normalize(img.name) === normalize(name));

export const getCover = (id: string): ProjectImage =>
  findImage(id, "cover") ?? ERR_IMG;

export const getHeaderPic = (id: string): ProjectImage =>
  findImage(id, "header") ?? ERR_IMG;

export const getMainCover = (id: string): ProjectImage =>
  findImage(id, "cover_main") ?? getCover(id);

/** Skip speculative fetching on data-saver / very slow connections. */
export const canPrefetch = () => {
  const c = (
    navigator as Navigator & {
      connection?: { saveData?: boolean; effectiveType?: string };
    }
  ).connection;
  return !(c?.saveData || /^(slow-)?2g$/.test(c?.effectiveType ?? ""));
};

/** Warm the cache for what a project card opens into (header + first gallery images). */
export const prefetchProject = (id: string) => {
  if (!canPrefetch()) return;
  const header = getHeaderPic(id);
  if (header !== ERR_IMG) void preloadImage(header.src);
  getImages(id)
    .slice(0, 4)
    .forEach((i) => void preloadImage(i.src));
};

/** Covers of every project, e.g. before navigating to the Projects page. */
export const warmProjectCovers = () => {
  if (!canPrefetch()) return;
  for (const id of Object.keys(imagesById)) {
    const c = getCover(id);
    if (c !== ERR_IMG) void preloadImage(c.src);
  }
};

/** First few images of every hobby stack on the About page. */
export const warmHobbyImages = () => {
  if (!canPrefetch()) return;
  for (const id of Object.keys(imagesById))
    if (id.startsWith("hobbies/"))
      getImages(id)
        .slice(0, 3)
        .forEach((i) => void preloadImage(i.src));
};

export const warmRoute = (to: string) => {
  if (to === "/projects") warmProjectCovers();
  else if (to === "/about") warmHobbyImages();
};

export const formatStarted = (d: Date) =>
  d.toLocaleDateString("en", { month: "short", year: "numeric" });
